selected.compute:
pool = read('/input/options')
result = None
for count in reversed(range(goal['min_count'], goal['max_count'] + 1)):
    for group in combinations(pool, count):
        proposal = [entry['id'] for entry in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

selected.effects:
artifact = read('/output/selection')
if artifact is not None:
    result = artifact
    if valid(result):
        delivery = receipt('report')
        if delivery == 'success':
            pass
        elif delivery == 'unknown':
            delivery_status = status('report')
            if delivery_status == 'not_sent':
                send('report', 'team', result)
        elif delivery == 'unattempted' or delivery == 'failure':
            send('report', 'team', result)
else:
    if result is not None and valid(result):
        write('/output/selection', result)
        send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
